### 3. Smart Contract Implementation (Solidity)

This contract acts as the **Root of Trust**. It does not store the art, only the hash of the Provenance Bundle and the Museum's Decentralized Identifier (DID).

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract ArtifexRegistry {

    struct ProvenanceRecord {
        bytes32 manifestHash;       // Hash of the JSON-LD Manifest
        bytes32 sourceHash;         // Hash of the Historical Source Material
        address registrar;          // Museum Wallet Address
        uint256 timestamp;
        bool isAIReconstruction;    // Flag to explicitly mark AI content
    }

    mapping(bytes32 => ProvenanceRecord) public records;
    mapping(address => bool) public authorizedInstitutions;

    event ArtifactRegistered(bytes32 indexed recordId, bytes32 manifestHash, bool isAI);

    constructor(address[] memory _initialInstitutions) {
        for (uint i = 0; i < _initialInstitutions.length; i++) {
            authorizedInstitutions[_initialInstitutions[i]] = true;
        }
    }

    /**
     * @notice Anchors the hash of a Provenance Bundle to the blockchain
     */
    function anchorProvenance(
        bytes32 _manifestHash, 
        bytes32 _sourceHash, 
        bool _isAIReconstruction
    ) public returns (bytes32) {
        require(authorizedInstitutions[msg.sender], "Unauthorized Institution");

        bytes32 recordId = keccak256(abi.encodePacked(_manifestHash, block.timestamp));

        records[recordId] = ProvenanceRecord({
            manifestHash: _manifestHash,
            sourceHash: _sourceHash,
            registrar: msg.sender,
            timestamp: block.timestamp,
            isAIReconstruction: _isAIReconstruction
        });

        emit ArtifactRegistered(recordId, _manifestHash, _isAIReconstruction);
        return recordId;
    }

    /**
     * @notice Verify if a bundle hash exists on-chain and matches the expected manifest
     */
    function verifyIntegrity(bytes32 _recordId, bytes32 _expectedManifestHash) public view returns (bool) {
        return records[_recordId].manifestHash == _expectedManifestHash;
    }
}
```

### 4. Implementation Logic (Python)

This script handles the ingestion, hashing, signing, and anchoring process.

```python
import hashlib
import json
import time
from web3 import Web3
from eth_account import Account

class MuseumProvenanceProtocol:
    def __init__(self, provider_url, private_key):
        self.w3 = Web3(Web3.HTTPProvider(provider_url))
        self.account = Account.from_key(private_key)

    def generate_content_hash(self, data):
        """Generates a SHA-256 hash of any digital artifact."""
        if isinstance(data, str):
            data = data.encode('utf-8')
        return hashlib.sha256(data).hexdigest()

    def create_provenance_record(self, original_artifact, ai_model_metadata, reconstruction):
        """Links the original source, the AI model, and the output."""
        source_hash = self.generate_content_hash(original_artifact)
        model_hash = self.generate_content_hash(json.dumps(ai_model_metadata))
        output_hash = self.generate_content_hash(reconstruction)

        # Create the cryptographic link
        link_string = f"{source_hash}|{model_hash}|{output_hash}|{time.time()}"
        provenance_id = self.generate_content_hash(link_string)

        metadata = {
            "provenance_id": provenance_id,
            "source_hash": source_hash,
            "model_hash": model_hash,
            "output_hash": output_hash,
            "timestamp": time.time(),
            "artifact_type": "AI_Reconstruction"
        }
        return metadata

    def anchor_to_blockchain(self, metadata):
        """Commits the provenance metadata hash to the smart contract."""
        # In production, this would call the Smart Contract via Web3.py
        # contract.functions.anchorProvenance(manifest_hash, source_hash, True).transact(...)

        meta_string = json.dumps(metadata)
        tx_hash = self.w3.eth.send_transaction({
            'from': self.account.address,
            'to': self.account.address, # Self-transaction for anchoring
            'value': 0,
            'gas': 2000000,
            'data': self.w3.to_hex(text=meta_string)
        })
        return tx_hash.hex()

# Execution Example
protocol = MuseumProvenanceProtocol("http://127.0.0.1:8545", "0x...")
original_fragment = "C4-E4-G4-C5 (fragmented_score_01.mid)"
ai_model_info = {"model_name": "BachNet-v2", "weights_hash": "a3f12b...", "seed": 12345}
reconstructed_music = "C4-E4-G4-C5-B3-D4-G3-B3... (full_composition.mid)"

provenance_data = protocol.create_provenance_record(original_fragment, ai_model_info, reconstructed_music)
tx_id = protocol.anchor_to_blockchain(provenance_data)
print(f"Provenance ID: {provenance_data['provenance_id']}\nBlockchain Tx ID: {tx_id}")
```

### 5. Verification Workflow

To ensure the system works for the end-user (researcher or visitor), the following verification flow is established:
1. **Retrieve:** The user scans a QR code or clicks a digital badge, fetching the Provenance Bundle from IPFS.
2. **Validate Integrity:** The client hashes the downloaded files and compares them against the `contentHash` in the Bundle.
3. **Validate Authority:** The client checks the Museum's Digital Signature against their public DID and queries the Smart Contract to ensure the `manifestHash` was anchored by an `authorizedInstitutions` address.
4. **Display Provenance:** 
   - **Green Check:** "Verified Historical Fragment."
   - **Blue Check:** "Verified AI Reconstruction (Linked to Fragment)."
   - **Warning:** "Hash mismatch" or "Unanchored Record."

### 6. Ethical, Technical, & Governance Safeguards

1. **The "Hallucination" Disclaimer:** The metadata schema explicitly flags `type: "AI_Reconstruction"`. The cryptographic link proves the AI *used* the fragment, not that the AI output is historically accurate. The UI must render this distinction clearly.
2. **Model Weight Hashing:** To prevent "Model Drift" (where the AI changes its behavior over time), the hash of the specific model weights is recorded. If the museum updates the AI, a new bundle must be created.
3. **Right to Correction (Off-Chain Mutation):** If a reconstruction is proven wrong, do not delete the original chain entry. Instead, create a new Provenance Bundle referencing the old `bundleHash` as a `supersededBy` link, preserving the audit trail.
4. **Energy Efficiency:** Using a Proof-of-Stake (PoS) L2 chain ensures the carbon footprint of verifying the art does not outweigh the cultural value.
